import XCTest

class OpenDialogTest: XCTestCase {
    func testTapOpenButton() {
        let app = XCUIApplication()

        // Wait for the dialog to appear
        let openButton = app.buttons["Open"]
        XCTAssertTrue(openButton.waitForExistence(timeout: 5))

        // Tap the Open button
        openButton.tap()
    }
}
